-- Автопостинг, крок 3: карусель «Фішка» (слайди 4:5 у стилі каталогу, публікація в Instagram каруселлю)
UPDATE content_templates SET status = 'trial', slots = 'обкладинка (кадр + хук ≤50), 2–6 слайдів: кадр + теза ≤55 + пояснення ≤110, фінал + CTA, підпис', description = 'Обкладинка-хук на реальному рендері, слайд на кожен кадр (планування — цілим на білому), фінальний слайд із закликом і «збережіть»' WHERE key = 'carousel-feature';
INSERT INTO changelog (title, body, created_at) VALUES ('Автопостинг: карусель у стилі каталогу', 'Контент → Пости → «+ ідея», формат «Карусель» → відкрий пост: познач 3–7 кадрів з матеріалів (перший за № — обкладинка; планування показується цілим), впиши хук обкладинки, тези слайдів, фінал і підпис — або «Джері, заповни тексти» (пише тільки з фактів клієнта, теза під кожен кадр + підпис з хештегами). «Зібрати» — слайди 1080×1350: обкладинка на рендері зі смарагдовою хвилею, слайди «кадр + теза», фінал з кнопкою і «збережіть». «На апрув у Telegram» — приходить альбом слайдів + підпис з кнопками ✓ / ✕. Після ✓ виходить в Instagram каруселлю з підписом у свій час. Обмеження: максимум 7 кадрів; порядок — поле «№» у рядках слайдів.', datetime('now'));
